<?php
declare(strict_types=1);
require_once __DIR__.'/includes/auth.php';require_login();$error='';$uid=(int)user()['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');
 if($action==='details'){
  $name=trim((string)($_POST['full_name']??''));$school=trim((string)($_POST['school_name']??''));
  if(mb_strlen($name)<2||mb_strlen($name)>100||mb_strlen($school)<2||mb_strlen($school)>190)$error='Please enter a valid name and school.';
  else{$s=db()->prepare('UPDATE users SET full_name=?,school_name=? WHERE id=?');$s->bind_param('ssi',$name,$school,$uid);$s->execute();refresh_user();flash('success','Personal details updated successfully.');redirect('profile.php?tab=details');}
 }elseif($action==='password'){
  $old=(string)($_POST['old_password']??'');$new=(string)($_POST['new_password']??'');$row=query_one('SELECT password_hash FROM users WHERE id=?','i',[$uid]);
  if(!$row||!password_verify($old,$row['password_hash'])||strlen($new)<8||$new!==($_POST['confirm_password']??''))$error='Check your current password. The new password must contain at least 8 characters and both entries must match.';
  else{$h=password_hash($new,PASSWORD_DEFAULT);$s=db()->prepare('UPDATE users SET password_hash=? WHERE id=?');$s->bind_param('si',$h,$uid);$s->execute();flash('success','Password changed successfully.');redirect('profile.php?tab=security');}
 }elseif($action==='photo'){
  if(empty($_FILES['photo']['tmp_name'])||$_FILES['photo']['error']!==UPLOAD_ERR_OK)$error='Please choose an image to upload.';
  else{$f=$_FILES['photo'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;
   if(!$ext||$f['size']>MAX_PROFILE_IMAGE_BYTES)$error='Use a JPG, PNG or WebP image smaller than 2 MB.';
   else{$name='user_'.$uid.'_'.bin2hex(random_bytes(8)).'.'.$ext;$dest=__DIR__.'/uploads/profiles/'.$name;if(move_uploaded_file($f['tmp_name'],$dest)){$s=db()->prepare('UPDATE users SET profile_image=? WHERE id=?');$s->bind_param('si',$name,$uid);$s->execute();refresh_user();flash('success','Profile photo updated successfully.');redirect('profile.php');}else $error='The photo could not be saved. Please try again.';}
  }
 }
}
$lang=medium_language((string)user()['medium']);$mediumCopy=['en'=>'English Medium','si'=>'සිංහල මාධ්‍ය','ta'=>'தமிழ் மூலம்'][$lang];
$stats=query_one("SELECT (SELECT COALESCE(SUM(points),0) FROM student_points WHERE user_id=?) points,(SELECT COUNT(*) FROM lesson_progress WHERE user_id=? AND completed_at IS NOT NULL) lessons,(SELECT COUNT(*) FROM quiz_attempts WHERE user_id=?) quizzes,(SELECT COUNT(*) FROM student_emblems WHERE user_id=?) emblems",'iiii',[$uid,$uid,$uid,$uid])??[];
$initials='';foreach(preg_split('/\s+/u',trim((string)user()['full_name']))?:[] as $part)$initials.=mb_substr($part,0,1);$initials=mb_strtoupper(mb_substr($initials,0,2));
$requestedTab=(string)($_GET['tab']??'overview');$activeTab=in_array($requestedTab,['overview','details','security'],true)?$requestedTab:'overview';$pageTitle=tr('profile');include __DIR__.'/includes/header.php';
