<script>document.getElementById('changePhoto')?.addEventListener('click',()=>location.href='?tab=details#photoForm');const password=document.getElementById('newPassword'),strength=document.getElementById('passwordStrength');password?.addEventListener('input',()=>{const value=password.value;let score=0;if(value.length>=8)score++;if(/[A-Z]/.test(value)&&/[a-z]/.test(value))score++;if(/\d/.test(value))score++;if(/[^A-Za-z0-9]/.test(value))score++;strength.style.width=(score*25)+'%';strength.style.background=score<2?'#d83d55':score<4?'#ffb638':'#21c59b'});</script>
